import{_ as o,c as s,o as e,ag as n}from"./chunks/framework.Cycwnjj0.js";const r="/assets/open-desired-singlw-custom-product.DGI_MW29.webp",i="/assets/settings-sidebar-for-single-products.Cxb-tLX5.webp",a="/assets/single-products-settings-option.DRsdZHGO.webp",p="/assets/save-template-or-update-_-save-template-button.CTTnIwee.webp",u="/assets/open-desired-multiple-custom-products.C_QKILjR.webp",l="/assets/settings-sidebar-for-multiple-products.BOTgPP20.webp",g="/assets/multiple-products-settings-options.Dx1CmNAe.webp",c="/assets/save-template-or-update-_-save-template-button.CEUSKOhq.webp",_=JSON.parse(`{"title":"Settings for Custom Products' Template Customization","description":"","frontmatter":{},"headers":[],"relativePath":"guide/custom-product/settings-for-custom-products-template-customization.md","filePath":"guide/custom-product/settings-for-custom-products-template-customization.md"}`),d={name:"guide/custom-product/settings-for-custom-products-template-customization.md"};function m(h,t,f,b,y,S){return e(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="settings-for-custom-products-template-customization" tabindex="-1">Settings for Custom Products&#39; Template Customization <a class="header-anchor" href="#settings-for-custom-products-template-customization" aria-label="Permalink to &quot;Settings for Custom Products&#39; Template Customization&quot;">​</a></h1><p>AzonPress allows you to customize the template of your Custom Products feature for both Single and Multiple products. This article guides you through the process of how to customize the template of both <strong>Single Custom Products</strong> and <strong>Multiple Custom Products</strong> with the available <strong>Settings</strong> options in <strong>AzonPress</strong>.</p><h2 id="settings-for-single-custom-product" tabindex="-1">Settings for Single Custom Product <a class="header-anchor" href="#settings-for-single-custom-product" aria-label="Permalink to &quot;Settings for Single Custom Product&quot;">​</a></h2><p>To learn how to customize the template of Single Custom Products, follow the steps with screenshots below –</p><p>First, go to <strong>Custom Products</strong> from the <strong>AzonPress Navbar</strong> and open your <strong>desired</strong> Single <strong>Custom Product</strong> that you want to customize.</p><p><img src="'+r+'" alt="Open desired Single custom Product"></p><p>Once you open the product, you will find the <strong>Settings</strong> option on the right-hand sidebar.</p><p><img src="'+i+'" alt="Settings Sidebar for Single Products"></p><p>Now, all the available <strong>Settings</strong> options for customization are briefly explained in the screenshot below:</p><p><strong>Choose Template</strong>: This option provides <strong>two inbuilt templates</strong> for displaying your products, you can choose anyone according to your needs.</p><p><strong>Changing Color</strong>: With the options under settings, you can customize the colors of your template&#39;s <strong>background</strong>, <strong>text</strong>, <strong>border</strong>, <strong>heading</strong>, and <strong>primary</strong> color using the default options or the color palette.</p><p><strong>Link Redirect Type</strong>: From here you can set your link redirection type that how you want your link to be redirected.</p><p><strong>Open Links in a New Window</strong>: Your link will be open on a new page if you enable this option.</p><p><strong>Use No Follow on Links</strong>: You can enable this if you want to enable no follow for your link.</p><p><strong>Add Additional Rel Attribute Tags</strong>: You can add additional rel attribute tags from here.</p><p><strong>Add Link Query Params</strong>: This option is for Adding Query Params on your affiliate link. To know more read this <a href="/guide/miscellaneous/affiliate-link-configuration.html">Documentation</a>.</p><p><img src="'+a+'" alt="Single products Settings option"></p><p>After setting up all the customization, click the <strong>Save Template</strong> or <strong>Update &amp; Save Template</strong> button to make sure all the changes must appear on your site.</p><p><img src="'+p+'" alt="Single products Save Template or Update &amp; Save Template button"></p><h2 id="settings-for-multiple-custom-products" tabindex="-1">Settings for Multiple Custom Products <a class="header-anchor" href="#settings-for-multiple-custom-products" aria-label="Permalink to &quot;Settings for Multiple Custom Products&quot;">​</a></h2><p>To learn how to customize the template of Multiple Custom Products, follow the steps with screenshots below –</p><p>First, go to <strong>Custom Products</strong> from the <strong>AzonPress Navbar</strong> and open your <strong>desired</strong> Multiple <strong>Custom Products</strong> that you want to customize.</p><p><img src="'+u+'" alt="Open desired Multiple custom products"></p><p>Once you open the product, you will find the <strong>Settings</strong> option on the right-hand sidebar.</p><p><img src="'+l+'" alt="Settings Sidebar for Multiple Products"></p><p>Now, all the available <strong>Settings</strong> options for customization are briefly explained in a screenshot below:</p><p>The <strong>Settings</strong> options of <strong>Multiple Custom Products</strong> are <strong>almost the same as</strong> the <strong>Single Custom Product</strong>, <strong>except</strong> for the very last <strong>Button Settings</strong> option. This is why, here, I will explain only the <strong>Button Settings</strong> below.</p><p><strong>Button Settings</strong>: With this option, you <strong>can modify the text</strong> of the &quot;<strong>Buy Now</strong>&quot; button. Additionally, you can <strong>Disable</strong> and <strong>Enable</strong> this button by clicking the orange <strong>Toggle</strong>.</p><p><img src="'+g+'" alt="Multiple Products Settings options"></p><p>Once you are setting up all the customization, click the <strong>Save Template</strong> or <strong>Update &amp; Save Template</strong> button to make sure all the changes appear on your site.</p><p><img src="'+c+'" alt="Multiple Products Save Template or Update &amp; Save Template button"></p><p>This is how you can customize the Template of your Single or Multiple Custom Products!</p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',34)])])}const P=o(d,[["render",m]]);export{_ as __pageData,P as default};
